def intersection(nums1: list[int], nums2: list[int]) -> list[int]:
    # Convert smaller array to set to minimize memory
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    set1 = set(nums1)
    result = set()
    for x in nums2:
        if x in set1:
            result.add(x)
    return list(result)
```
